from pathlib import Path
import base64
import json
import html

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'result'
def image(name, alt=''):
    data = base64.b64encode((OUT / name).read_bytes()).decode()
    return f'<img alt="{html.escape(alt)}" src="data:image/png;base64,{data}">'

metrics = json.loads((OUT / 'juice_extended_metrics_2026-10-27.json').read_text(encoding='utf-8-sig'))['total']
